INSERT INTO schema_migrations(version,name,checksum)
SELECT '0008','0008_bcmd_batch.sql','4d80f0147118451c31fc9eef3a2e77ad759046e32eccd2cb6e9574f8cb480461'
WHERE @napa_pre_ok AND @napa_post_ok AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version='0008');
SELECT '0008' AS version,
 CASE WHEN @napa_pre_ok AND @napa_post_ok AND (SELECT COUNT(*) FROM schema_migrations WHERE version='0008' AND name='0008_bcmd_batch.sql' AND checksum='4d80f0147118451c31fc9eef3a2e77ad759046e32eccd2cb6e9574f8cb480461')=1 THEN 'VERIFIED'
      WHEN @napa_target_ok AND @napa_locked=1 AND @napa_post_ok AND (SELECT COUNT(*) FROM schema_migrations WHERE version='0008' AND name='0008_bcmd_batch.sql' AND checksum='4d80f0147118451c31fc9eef3a2e77ad759046e32eccd2cb6e9574f8cb480461')=1 THEN 'ALREADY_RECORDED'
      ELSE 'STOP' END AS step_status,
 @napa_target_ok AS target_ok,@napa_pre_ok AS preflight_ok,@napa_post_ok AS postflight_ok;
SELECT IF(@napa_locked=1,RELEASE_LOCK('tuloy_schema_migrate'),0) AS migration_lock_released;
